import React, { createContext, useState, useContext, useEffect } from 'react';
import { api, setAuthToken, clearAuthToken } from '../utils/api';

const AuthContext = createContext(null);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Check if user is authenticated on mount and when needed
  const checkAuth = async () => {
    try {
      setLoading(true);
      setError(null);
      // First check if token exists by calling authenticate endpoint
      try {
        const authResponse = await api.post('/auth/authenticate');

        if (authResponse.error && authResponse.error !== "") {
          setUser(null);
          clearAuthToken();
          return;
        }

        // Store the token from authenticate response
        if (authResponse.data) {
          setAuthToken(authResponse.data);
        }

        // If authenticated, fetch full user data
        const userResponse = await api.get('/users/me');
        if (userResponse.user) {
          setUser(userResponse.user);
        } else {
          setUser(null);
          clearAuthToken();
        }
      } catch (authErr) {
        // If authenticate fails, user is not authenticated
        setUser(null);
        clearAuthToken();
      }
    } catch (err) {
      console.error('Auth check failed:', err);
      setUser(null);
      clearAuthToken();
      // Don't set error for normal unauthenticated state
    } finally {
      setLoading(false);
    }
  };

  // Login function
  const login = async (email, password) => {
    try {
      setLoading(true);
      setError(null);
      const response = await api.post('/auth/login', {
        email,
        password,
      });

      // Get token from authenticate endpoint after login
      try {
        const authResponse = await api.post('/auth/authenticate');
        if (authResponse.data && !authResponse.error) {
          setAuthToken(authResponse.data);
        }
      } catch (authErr) {
        console.error('Failed to get token after login:', authErr);
      }

      // Fetch user data after successful login
      try {
        const userResponse = await api.get('/users/me');
        if (userResponse.user) {
          setUser(userResponse.user);
        }
      } catch (userErr) {
        console.error('Failed to fetch user after login:', userErr);
      }

      return { success: true, data: response.data };
    } catch (err) {
      const errorMessage = typeof err === 'string' ? err : (err.message || 'Login failed');
      setError(errorMessage);
      clearAuthToken();
      throw new Error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  // Register function
  const register = async (userData) => {
    try {
      setLoading(true);
      setError(null);
      const response = await api.post('/auth/register', {
        full_name: userData.fullName,
        email: userData.email,
        password: userData.password,
        repeated_password: userData.repeatPassword,
      });

      // Get token from authenticate endpoint after registration
      try {
        const authResponse = await api.post('/auth/authenticate');
        if (authResponse.data && !authResponse.error) {
          setAuthToken(authResponse.data);
        }
      } catch (authErr) {
        console.error('Failed to get token after registration:', authErr);
      }

      // Fetch user data after successful registration
      try {
        const userResponse = await api.get('/users/me');
        if (userResponse.user) {
          setUser(userResponse.user);
        }
      } catch (userErr) {
        console.error('Failed to fetch user after registration:', userErr);
      }

      return { success: true, data: response.data };
    } catch (err) {
      const errorMessage = typeof err === 'string' ? err : (err.message || 'Registration failed');
      setError(errorMessage);
      clearAuthToken();
      throw new Error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  // Logout function
  const logout = async () => {
    try {
      setLoading(true);
      await api.post('/auth/logout');
      setUser(null);
      setError(null);
      clearAuthToken();
    } catch (err) {
      console.error('Logout failed:', err);
      // Clear user state even if logout request fails
      setUser(null);
      clearAuthToken();
    } finally {
      setLoading(false);
    }
  };

  // Refresh user data
  const refreshUser = async () => {
    try {
      // Ensure we have a token before making the request
      try {
        const authResponse = await api.post('/auth/authenticate');
        if (authResponse.data && !authResponse.error) {
          setAuthToken(authResponse.data);
        } else {
          setUser(null);
          clearAuthToken();
          return;
        }
      } catch (authErr) {
        setUser(null);
        clearAuthToken();
        return;
      }

      const userResponse = await api.get('/users/me');
      if (userResponse.user) {
        setUser(userResponse.user);
      } else {
        setUser(null);
        clearAuthToken();
      }
    } catch (err) {
      console.error('Failed to refresh user data:', err);
      setUser(null);
      clearAuthToken();
    }
  };

  // Check authentication on mount
  useEffect(() => {
    checkAuth();
  }, []);

  const value = {
    user,
    loading,
    error,
    isAuthenticated: !!user,
    login,
    register,
    logout,
    checkAuth,
    refreshUser,
    setUser,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};
